import JoeRedesign from '@/components/redesign/JoeRedesign';
import { getRedesignContent } from '@/components/redesign/content';
import { fontVariables } from './fonts';
import './redesign.css';
import { DEFAULT_LOCALE, LANG_CODE, LOCALES, SITE_URL, localeUrl } from '@/lib/site';

// 1200×630 share card generated by scripts/brand-assets.cjs.
const OG_IMAGE = { url: `${SITE_URL}/og-image.png`, width: 1200, height: 630, type: 'image/png' };

export async function generateMetadata({ params: { locale } }) {
  const copy = getRedesignContent(locale);
  const { title, description, ogAlt } = copy.meta;
  const url = localeUrl(locale);
  return {
    title,
    description,
    keywords: copy.services.items.map(s => s.title).concat(locale === 'ar' ? ['شركة برمجيات', 'السعودية', 'الخليج'] : ['software company', 'Saudi Arabia', 'Gulf']),
    authors: [{ name: copy.brand, url: SITE_URL }],
    creator: copy.brand,
    publisher: copy.brand,
    category: 'technology',
    openGraph: {
      type: 'website',
      siteName: copy.brand,
      locale: locale === 'ar' ? 'ar_SA' : 'en_US',
      alternateLocale: locale === 'ar' ? ['en_US'] : ['ar_SA'],
      url,
      title,
      description,
      images: [{ ...OG_IMAGE, alt: ogAlt }],
    },
    twitter: { card: 'summary_large_image', title, description, images: [OG_IMAGE.url] },
    alternates: {
      canonical: url,
      languages: {
        ...Object.fromEntries(LOCALES.map(l => [LANG_CODE[l], localeUrl(l)])),
        'x-default': localeUrl(DEFAULT_LOCALE),
      },
    },
    robots: { index: true, follow: true, 'max-image-preview': 'large', 'max-snippet': -1, 'max-video-preview': -1 },
  };
}

export const viewport = {
  themeColor: [
    { media: '(prefers-color-scheme: dark)', color: '#03060f' },
    { media: '(prefers-color-scheme: light)', color: '#f4f6fb' },
  ],
  colorScheme: 'dark light',
};

export default function HomePage({ params: { locale } }) {
  return <JoeRedesign locale={locale} fontClassName={fontVariables} />;
}
